    const current = z ?? { c, r, v: 0, bv: 0, ct: 0, bt: 0 };
    const n = Math.round(Math.log2(ts)), m = Math.round(Math.log2(ps)), rowHistory = cellHistory(n, m, c, r, last.cut);
    const history = rowHistory.samples.map((sample) => sample?.z ?? null);
