      pane =
        !col
          ? []
          : S.mode === "path"
            ? [["Column path ÷ range", col.ct > 0 && col.hi > col.lo ? compact(col.p / (col.hi - col.lo)) : "—"]]
            : [["Column USDT ÷ path", col.p > 0 ? compact(col.v / col.p) : "—"]],
