      notes =
        key === "cascade" && x.alone
          ? "The other column in its parent had no trades"
          : key === "efficiency"
            ? `Its USDT per 125 USDT row its trades touched, over its parent column's, against the ${EFFICIENCY_EXPECTED.toFixed(2)} the recorded model expects`
            : "";
