      ctx.strokeStyle = colors.surface;
      ctx.globalAlpha = 0.7;
      ctx.lineWidth = 3.5;
      ctx.stroke();
      ctx.globalAlpha = 1;
      ctx.strokeStyle = colors.poc;
      ctx.lineWidth = 1.7;
      ctx.stroke();
