      // transparency for all three (PRD-0002 S3 section 1).
      if (xa > xl) stroke(style.colour, width, E.role.REFERENCE.PATTERN.lead.join(","), 1, xl, y, xa);
      if (xb > xa) stroke(style.colour, width, "", 1, xa, y, xb);
      if (l.on && right > xb) stroke(style.colour, width, E.role.REFERENCE.PATTERN.held.join(","), 1, xb, y, right);
